with remaining_keys as (select supplier_id, id from products except select supplier_id, id from products where cost between 270 and 330), verified as (select s.* from products s inner join remaining_keys k on s.supplier_id = k.supplier_id and s.id = k.id) select supplier_id, round(avg(cost), 2) as avg_cost, max(stock_qty) filter (where category = 'Electronics') as electronics_max_stock_qty from verified group by supplier_id order by electronics_max_stock_qty desc nulls last
